package exec

import (
	"syscall"

	"github.com/jokruger/kavun/core"
	"github.com/jokruger/kavun/core/member"
	"github.com/jokruger/kavun/errs"
)

// exec.process's members: one function per member, each declared by the //kavun:member directive in its doc comment.
// The table, processMethods, and the member entries of docs/reference/types/exec_process.md (alphabetical, so the order
// here is free) are generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Report truthiness: a process is always truthy.
//
//kavun:member is_true pure () -> bool
func processIsTrue(_ core.VM, v core.Value, _ member.ID, _ []core.Value) (core.Value, error) {
	t, err := core.ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return core.Undefined, err
	}
	return core.BoolValue(t), nil
}

// Render the process per the [format mini-language](../../format_mini_language.md).
//
//kavun:member format pure ([spec]) -> string
func processFormat(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	return core.FormatWithSpec(v, id, args)
}

// Answer the process itself.
//
//kavun:member copy pure () -> exec.process
func processCopy(_ core.VM, v core.Value, _ member.ID, _ []core.Value) (core.Value, error) {
	return v, nil
}

// Answer the process itself; see [`copy`](#copy).
//
//kavun:member freeze pure () -> exec.process
func processFreeze(_ core.VM, v core.Value, _ member.ID, _ []core.Value) (core.Value, error) {
	return v, nil
}

func processContext(id member.ID) string {
	return "exec.process." + id.String()
}

// Answer the process id.
//
//kavun:member pid impure () -> int
func processPid(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	return core.IntValue(int64(ProcessOf(v).Pid)), nil
}

// Kill the process.
//
//kavun:member kill impure () -> undefined
func processKill(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	if err := ProcessOf(v).Kill(); err != nil {
		return core.Undefined, errs.NewIOError(processContext(id), err)
	}
	return core.Undefined, nil
}

// Send the signal `sig` to the process.
//
//kavun:member signal impure (sig) -> undefined
func processSignal(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	sig, ok := args[0].AsInt()
	if !ok {
		return core.Undefined, errs.NewInvalidArgumentTypeError(processContext(id), "first", "int(compatible)", args[0].TypeName())
	}
	if err := ProcessOf(v).Signal(syscall.Signal(sig)); err != nil {
		return core.Undefined, errs.NewIOError(processContext(id), err)
	}
	return core.Undefined, nil
}

// Block until the process ends and answer the frozen record `{pid, exited, success, status}`.
//
// The record holds facts, not behaviour (`status` is the system's text: `"exit status 3"`, `"signal: killed"`).
//
//kavun:member wait impure () -> record
func processWait(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	state, err := ProcessOf(v).Wait()
	if err != nil {
		return core.Undefined, errs.NewIOError(processContext(id), err)
	}
	return NewWaitValue(state), nil
}

// Release the resources held for the process.
//
//kavun:member release impure () -> undefined
func processRelease(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	if err := ProcessOf(v).Release(); err != nil {
		return core.Undefined, errs.NewIOError(processContext(id), err)
	}
	return core.Undefined, nil
}
